import sqlite3
import json

DB_PATH = "data/f1.sqlite"
conn = sqlite3.connect(DB_PATH)
conn.row_factory = sqlite3.Row
cur = conn.cursor()

# Verify Part C counts
cur.execute("""
    SELECT race_id, driver_id, lap, position
    FROM lap_positions WHERE lap_type = 'Race'
    ORDER BY race_id, lap, position
""")
race_positions = {}
for row in cur.fetchall():
    r, d, l, p = row["race_id"], row["driver_id"], row["lap"], row["position"]
    race_positions.setdefault(r, {}).setdefault(l, {})[d] = p

cur.execute("SELECT race_id, driver_id, grid FROM results WHERE grid > 0")
grid_positions = {}
for row in cur.fetchall():
    grid_positions.setdefault(row["race_id"], {})[row["driver_id"]] = row["grid"]

cur.execute("SELECT race_id, driver_id, lap FROM retirements")
retirements = {}
for row in cur.fetchall():
    retirements[(row["race_id"], row["driver_id"], row["lap"])] = True

cur.execute("SELECT race_id, driver_id, lap FROM pit_stops")
pit_stops = {}
for row in cur.fetchall():
    pit_stops[(row["race_id"], row["driver_id"], row["lap"])] = True

# Compute all events
t_overtook = {}
t_was_overtaken = {}

for race_id in race_positions:
    laps = sorted(race_positions[race_id].keys())
    race_grid = grid_positions.get(race_id, {})

    for li in range(len(laps)):
        lap = laps[li]
        if lap == 1:
            prev_state = race_grid
        else:
            prev_lap = laps[li - 1]
            if prev_lap != lap - 1:
                continue
            prev_state = race_positions[race_id][prev_lap]

        curr_state = race_positions[race_id][lap]
        common = set(prev_state.keys()) & set(curr_state.keys())

        for dA in common:
            for dB in common:
                if dA >= dB:
                    continue
                pA_prev, pB_prev = prev_state[dA], prev_state[dB]
                pA_curr, pB_curr = curr_state[dA], curr_state[dB]

                if pA_prev < pB_prev and pA_curr > pB_curr:
                    overtaking, overtaken = dB, dA
                elif pB_prev < pA_prev and pB_curr > pA_curr:
                    overtaking, overtaken = dA, dB
                else:
                    continue

                # Classify
                if (race_id, overtaken, lap) in retirements:
                    cat = "R"
                elif (race_id, overtaken, lap) in pit_stops or (race_id, overtaken, lap-1) in pit_stops:
                    cat = "P"
                elif lap == 1:
                    g_ot = race_grid.get(overtaking)
                    g_otd = race_grid.get(overtaken)
                    if g_ot is not None and g_otd is not None and abs(g_ot - g_otd) <= 2:
                        cat = "S"
                    else:
                        cat = "T"
                else:
                    cat = "T"

                if cat == "T":
                    t_overtook[overtaking] = t_overtook.get(overtaking, 0) + 1
                    t_was_overtaken[overtaken] = t_was_overtaken.get(overtaken, 0) + 1

# Print summary
total_t_events = sum(t_overtook.values())
total_drivers = len(set(t_overtook.keys()) | set(t_was_overtaken.keys()))
deficit = []
for d in set(t_overtook.keys()) | set(t_was_overtaken.keys()):
    ot = t_overtook.get(d, 0)
    wot = t_was_overtaken.get(d, 0)
    if wot > ot:
        deficit.append(d)

print(f"Total T events: {total_t_events}")
print(f"Total drivers with T events: {total_drivers}")
print(f"Drivers with was_overtaken > overtook: {len(deficit)}")
print(f"Sum of overtook: {sum(t_overtook.values())}")
print(f"Sum of was_overtaken: {sum(t_was_overtaken.values())}")

cur.execute("SELECT COUNT(DISTINCT driver_id) FROM drivers")
total_drivers_all = cur.fetchone()[0]
print(f"Total drivers in DB: {total_drivers_all}")

conn.close()
